import 'package:flutter/material.dart';
import '../models/battle_v4_models.dart';import 'battle_status_strip_v4.dart';export 'battle_controls_v4.dart';
class TimelineV4 extends StatelessWidget{const TimelineV4({super.key,required this.ids,required this.units});final List<String> ids;final List<V4BattleUnit> units;@override Widget build(BuildContext context){final byId={for(final u in units)u.id:u};return DecoratedBox(decoration:BoxDecoration(color:const Color(0xB8101117),borderRadius:BorderRadius.circular(22),border:Border.all(color:const Color(0x554E5260))),child:Row(mainAxisAlignment:MainAxisAlignment.center,children:[for(var i=0;i<ids.length;i++)Padding(padding:EdgeInsets.symmetric(horizontal:i==0?5:3),child:_TimelineEntry(unit:byId[ids[i]],current:i==0))]));}}
class _TimelineEntry extends StatelessWidget{const _TimelineEntry({required this.unit,required this.current});final V4BattleUnit? unit;final bool current;@override Widget build(BuildContext context){final enemy=unit?.team==V4Team.enemy;final border=enemy?const Color(0xFFD15B5B):const Color(0xFF61A7E8);return AnimatedContainer(duration:const Duration(milliseconds:120),width:current?40:34,height:current?40:34,decoration:BoxDecoration(shape:BoxShape.circle,color:const Color(0xFF292B34),border:Border.all(color:border,width:current?3:2)),alignment:Alignment.center,child:Text(unit?.name.characters.first.toUpperCase()??'?',style:TextStyle(fontSize:current?16:13,fontWeight:FontWeight.bold,color:Colors.white)));}}
class PartyHudV4 extends StatelessWidget{const PartyHudV4({super.key,required this.party});final List<V4BattleUnit> party;@override Widget build(BuildContext context)=>DecoratedBox(decoration:BoxDecoration(color:const Color(0xC412131A),borderRadius:BorderRadius.circular(10),border:Border.all(color:const Color(0x553C4050))),child:Padding(padding:const EdgeInsets.all(6),child:Column(mainAxisAlignment:MainAxisAlignment.spaceEvenly,children:[for(final u in party)_PartyRow(unit:u)])));}
class _PartyRow extends StatelessWidget{const _PartyRow({required this.unit});final V4BattleUnit unit;@override Widget build(BuildContext context)=>Row(children:[CircleAvatar(radius:12,backgroundColor:const Color(0xFF363946),child:Text(unit.name.characters.first,style:const TextStyle(fontSize:11))),const SizedBox(width:6),Expanded(child:Column(mainAxisSize:MainAxisSize.min,children:[_bar(unit.hpRatio,const Color(0xFF5DBB72)),if(unit.maxMp>0)...[const SizedBox(height:3),_bar(unit.mpRatio,const Color(0xFF5E8DDB),height:4)]])),const SizedBox(width:5),BattleStatusStripV4(statuses:unit.statuses,barrier:unit.barrier,maxIcons:3,compact:true),const SizedBox(width:4),Text('${unit.hp}',style:const TextStyle(fontSize:10,color:Color(0xFFE2DFEA)))]);Widget _bar(double v,Color c,{double height=6})=>ClipRRect(borderRadius:BorderRadius.circular(height),child:SizedBox(height:height,child:LinearProgressIndicator(value:v.clamp(0.0,1.0).toDouble(),backgroundColor:const Color(0xFF242630),valueColor:AlwaysStoppedAnimation(c))));}
